/**
 * Generates `src/elements/reframed/document-facade/document-surface.generated.ts`.
 *
 * The generated file enumerates the spec-defined API surface of the `Document` interface — including all partial
 * interface declarations and interface mixins (e.g. ParentNode, DocumentOrShadowRoot, GlobalEventHandlers) — as well
 * as the inherited `Node` and `EventTarget` interfaces.
 *
 * The WebIDL definitions are sourced from https://github.com/w3c/webref (via the @webref/idl package), which curates
 * machine-readable WebIDL extracted from the latest editor's drafts of all browser specifications.
 *
 * The document facade (see `document-facade.ts`) uses this manifest to distinguish spec-defined Document APIs that
 * have not yet been audited for reframed contexts (and should produce a dev-mode diagnostic when used by a fragment)
 * from application-defined expando properties (which pass through silently).
 *
 * Regenerate with: pnpm generate:document-surface
 */
import { parseAll } from '@webref/idl';
import { writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const webrefVersion = require('@webref/idl/package.json').version;

const OUTPUT_PATH = new URL('../src/elements/reframed/document-facade/document-surface.generated.ts', import.meta.url);

/** Interfaces whose members are collected in addition to Document and its mixins. */
const INHERITED_INTERFACES = ['Node', 'EventTarget'];

const specs = await parseAll();
const allDefs = Object.values(specs).flat();

// Find all mixins included by Document (e.g. `Document includes ParentNode;`)
const documentMixins = allDefs
	.filter((def) => def.type === 'includes' && def.target === 'Document')
	.map((def) => def.includes);

/** @type {Map<string, { kind: string; from: string }>} */
const members = new Map();

/**
 * Collects named attribute and operation members declared by the given interface or mixin
 * (including partial declarations). Constructors, constants, static and special members
 * (indexed/named getters, setters, deleters, stringifiers, iterables) are not collected
 * as they are not accessed as named properties by application code.
 *
 * The first interface to declare a member wins, so collection order determines the `from`
 * attribution for the (rare) colliding member names.
 */
function collectMembers(interfaceName) {
	const defs = allDefs.filter(
		(def) => (def.type === 'interface' || def.type === 'interface mixin') && def.name === interfaceName,
	);

	for (const def of defs) {
		for (const member of def.members ?? []) {
			if (!member.name) continue;
			if (member.special === 'static') continue;

			if (member.type === 'attribute' || member.type === 'operation') {
				if (!members.has(member.name)) {
					members.set(member.name, { kind: member.type, from: interfaceName });
				}
			}
		}
	}
}

collectMembers('Document');
documentMixins.forEach(collectMembers);
INHERITED_INTERFACES.forEach(collectMembers);

const sortedMembers = [...members.entries()].sort(([a], [b]) => (a < b ? -1 : 1));

const entries = sortedMembers
	.map(([name, { kind, from }]) => `\t${name}: { kind: '${kind}', from: '${from}' },`)
	.join('\n');

const output = `/**
 * GENERATED FILE — DO NOT EDIT!
 *
 * Generated by scripts/generate-document-surface.mjs from @webref/idl@${webrefVersion}.
 * Regenerate with: pnpm generate:document-surface
 *
 * Enumerates the spec-defined API surface of the Document interface (including partials and mixins such as
 * ${documentMixins.join(', ')})
 * as well as the inherited Node and EventTarget interfaces.
 */

export interface DocumentSurfaceMember {
	/** Whether the member is declared as a WebIDL attribute or operation. */
	kind: 'attribute' | 'operation';
	/** The interface or mixin that declares the member. */
	from: string;
}

/**
 * All named properties that browsers expose on a Document instance per the current browser specifications.
 */
export const documentSurface: Readonly<Record<string, DocumentSurfaceMember>> = {
${entries}
};
`;

await writeFile(OUTPUT_PATH, output);
console.log(`Generated ${OUTPUT_PATH.pathname} with ${members.size} members from @webref/idl@${webrefVersion}`);
